package com.greenocean.backend;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PhaseP5MigrationTest extends MigrationTestSupport {
 @Test void forwardUpgradePreservesMetadataAndDoesNotInferRetention(){String url=System.getenv("GREENOCEAN_TEST_DB_URL"),schema="qa_p5_upgrade_"+UUID.randomUUID().toString().replace("-","");var source=new DriverManagerDataSource(url,System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD",""));Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("80").load().migrate();var db=new JdbcTemplate(new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema+",public",System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD","")));try{UUID u=db.queryForObject("INSERT INTO users(email,password_hash,status) VALUES('p5-upgrade@example.test','synthetic','ACTIVE') RETURNING id",UUID.class);db.execute("CREATE TABLE clinic_rights_requests(synthetic_conflict INTEGER)");assertThatThrownBy(()->Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load().migrate()).isInstanceOf(Exception.class);assertThat(db.queryForObject("SELECT count(*) FROM information_schema.tables WHERE table_schema=? AND table_name='clinic_followups'",Integer.class,schema)).isZero();db.execute("DROP TABLE clinic_rights_requests");Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load().migrate();assertThat(db.queryForObject("SELECT status FROM users WHERE id=?",String.class,u)).isEqualTo("ACTIVE");assertThat(db.queryForObject("SELECT count(*) FROM clinic_data_classes WHERE retention LIKE 'UNAPPROVED%'",Integer.class)).isEqualTo(14);assertThat(db.queryForObject("SELECT count(*) FROM clinic_followups",Integer.class)).isZero();}finally{db.execute("DROP SCHEMA "+schema+" CASCADE");}}
}
